	'step2_d' => 'Senden Sie das Formular oder schreiben Sie an hello@akiha-college.example.',
	'step3' => 'Grundausbildungsquartal, 12 Wochen',
	'step3_d' => 'Vollzeit an den Tafeln des Colleges.',
	'step4' => 'Probewoche bei einem Betrieb',
	'step4_d' => 'Fünf Tage auf der Baustelle, mit einem Besuch am dritten Tag.',
	'step5' => 'Für drei Jahre unter Vertrag',
	'step5_d' => 'Ein vom Betrieb unterzeichneter Vertrag: vier Tage auf der Baustelle, ein Tag hier.',
	'sub_h' => 'Die Briefe anfordern',
	'tagline' => 'Elektro-Ausbildungscollege · Seit 1998 · Calder Quay',
	'trial_h' => 'Eine Woche auf Ihrer Baustelle, mit einem Besuch an Tag drei.',
	'trial_p' => 'Bevor ein Vertrag unterzeichnet wird, verbringt der Auszubildende fünf Arbeitstage bei Ihrem Team. Die Prüferin kommt am dritten Tag, sieht der Arbeit zu und spricht mit Ihnen beiden.',
	'watch1_body' => 'Beim Befestigen eines armierten Kabels im Trennschalter zählt jede Drehung des Drehmomentschlüssels. Der Ausbilder achtet darauf, wie das Messinggewinde greift, ob die Armierungsdrähte sauber abgeschnitten sind, ohne den Innenmantel anzuritzen, und wie fest die Erdungsfahne sitzt. Eine Verschraubung dichtet entweder wirklich ab oder versagt unter Belastung.',
	'watch1_lead' => 'Die Verschraubung.',
	'watch2_body' => 'Saubere Stromkreisbeschriftungen zeigen, wie eine Elektrikerin oder ein Elektriker an die Person denkt, die den Verteiler als Nächstes öffnet. Der Ausbilder prüft, dass jeder Neutral- und Außenleiter genau zur Kennzeichnung seines Sicherungsautomaten passt, rechtwinklig abgelängt und ohne Kreuzungen gerade durch den Kanal geführt ist. Ein Verteiler, den man nicht auf einen Blick versteht, ist nicht fertig.',
	'watch2_lead' => 'Die Beschriftung.',
	'watch3_body' => 'Gute Installationsgewohnheiten zeigen sich im Umgang mit dem Werkzeug, lange bevor ein Messgerät eingeschaltet wird. Der Ausbilder beobachtet bewusste Freischaltprüfungen, ruhiges Abisolieren, das kein Kupfer anritzt, und die ständige Aufmerksamkeit für Haltung und Leitersicherheit. Methodische Disziplin lässt sich nicht vortäuschen, wenn jemand neben Ihrem Verteiler steht.',
	'watch3_lead' => 'Die Hände.',
	'watch_h' => 'Worauf der Ausbilder achtet',
	'week_c1_d' => 'Auf der Baustelle des Betriebs, neben einer Aufsicht.',
	'week_c1_t' => 'Vier Tage',
	'week_c2_d' => 'Zurück am College, an den Übungstafeln.',
	'week_c2_t' => 'Ein Tag',
	'week_c3_d' => 'Sechs abgenommene Arbeitsstücke in jedem Jahr.',
	'week_c3_t' => 'Drei Jahre',
	'week_h' => 'Vier Tage auf der Baustelle, ein Tag hier.',
	'week_p' => 'Jede Woche arbeitet ein Auszubildender vier Tage im Betrieb und kehrt am fünften Tag in die Werkstatt des Colleges zurück, wo ein Ausbilder abnimmt, was gebaut wurde.',
	'work_intro' => 'Wir bewerten unsere Ausbildung an der Haltbarkeit, Genauigkeit und Sauberkeit der Installationen, die unsere Auszubildenden auf aktiven Kundenbaustellen hinterlassen.',
	'work_s1_h' => 'Bäckerei-Umbau, Calder Quay — Joel Haddad',
	'work_s1_p' => 'Beim Umbau einer gewerblichen Bäckerei in Calder Quay übernahm Joel Haddad, Auszubildender im 2. Jahr, den kompletten Aufbau und Anschluss eines neuen Verteilers mit 14 Abgängen. In einer anspruchsvollen Gastronomieumgebung mit Feuchtigkeit, Mehlstaub und dauerhaften Maschinenlasten sind eine saubere Kabelführung und eine eindeutige Kennzeichnung der Stromkreise unverzichtbar. Joel ordnete jeden Stromkreis sauber im Gehäuse, befestigte die Leiter mit gleichmäßigem Abstand und beschriftete jeden abgehenden Sicherungsautomaten von Hand sowie jede Klemmenmarkierung. Die leitende Ausbilderin Rhea Lindqvist besuchte die Anlage, um Klemmen-Drehmomente, Phasenkennzeichnung und Erdungsdurchgang zu prüfen, bevor sie den Verteiler förmlich als fertiggestellt abnahm.',
	'work_s2_h' => 'Schulsporthalle — Amira Sesay',
	'work_s2_p' => 'Bei der umfassenden Sanierung einer Schulsporthalle verlegte Amira Sesay, Auszubildende im 1. Jahr, eine durchgehende, 38 Meter lange feuerverzinkte Kabelrinne in einer Höhe von vier Metern. Sie arbeitete sicher von fahrbaren Podesttreppen aus, maß mehrere Halterungen ab, fertigte sie an und befestigte sie an den stählernen Tragsäulen. Sie formte saubere Biegungen in Werksqualität und ebene Stöße über die gesamte Wandlänge. Die Kabel wurden mit gleichmäßigem Abstand geordnet und sauber festgebunden, damit sie Bauwerksschwingungen standhalten. Rhea Lindqvist prüfte die fertige Kabelführung vor Ort, kontrollierte die Tragfähigkeit der Halterungen und die Ausrichtung der Rinne und unterschrieb dann das Bewertungsblatt.',
	'work_s3_h' => 'Parkplatz einer Wohnungsgenossenschaft — Sven Aalto',
	'work_s3_p' => 'Auf dem Parkplatz einer Wohnungsgenossenschaft sollte Sven Aalto, Auszubildender im 3. Jahr, einen eigenen Ladestromkreis für Fahrzeuge installieren. Dafür musste ein kräftiges armiertes Kabel an der Außenwand aus Backstein entlanggeführt und fest in einen Industrie-Trennschalter neben einer Wandladestation angeschlossen werden. Sven entfernte den äußeren Schutzmantel, stellte mit korrekter Armierungsklemmung einen sauberen Abschluss in der Messingverschraubung her und zog alle mechanischen Verbindungen mit dem vorgeschriebenen Drehmoment an. Die Bewerterin vor Ort, Paloma Iturbe, führte während der Installation eine förmliche Baustellenbeobachtung durch und sah zu, wie Sven den Erdungsweg und die Wetterdichtungen prüfte, bevor sie ihre Unterschrift in sein Praxisbuch setzte.',
	'work_s4_h' => 'Aufzugsmaschinenraum — Noor Rahimi',
	'work_s4_p' => 'Im Maschinenraum einer Hochhausaufzuganlage führte Noor Rahimi, Auszubildende im 3. Jahr, die Fehlersuche und die vollständige elektrische Prüfung an einem gewerblichen Motor-Trennschalter durch. Sie arbeitete systematisch mit kalibrierten Prüfgeräten, verfolgte einen sporadischen Fehler im Steuerstromkreis und prüfte Durchgang und Isolationsfestigkeit über alle Phasen. Nach der Reparatur erstellte sie ein Inspektions- und Prüfblatt vollständig von Hand und trug die genauen Messwerte und Widerstandsberechnungen ein. Ausbilder Kofi Mensah prüfte ihre diagnostische Logik und kontrollierte die handgeschriebene Prüfdokumentation anhand der Protokolle des Digitalmessgeräts, bevor er das fertige Arbeitsstück abnahm.',
	'work_s5_h' => 'Die sechs Arbeitsstücke für den Jahresabschluss',
	'work_s5_p' => 'Der Fortschritt jedes Auszubildenden wird an sechs konkreten Nachweisen gemessen, die jedes Jahr entstehen. Diese sechs Ergebnisse müssen in fester Reihenfolge eingereicht werden: der Verteiler, die Kabelrinnenführung, die Verschraubung am armierten Kabel, das handgeschriebene Prüfblatt, die Bewertung des Baustellenbesuchs durch die Prüferin und das monatlich gegengezeichnete Berichtsheft des Betriebs. Die Ausbilder prüfen jedes Arbeitsstück persönlich. Es gibt keine automatisierten Prüfungen, keine Multiple-Choice-Abkürzungen und keine Ersatzaufgaben. Ein Ausbildungsjahr wird erst bescheinigt, wenn alle sechs abgenommenen Arbeitsstücke geprüft, genehmigt und in der dauerhaften Akte des Auszubildenden abgelegt sind.',
	'yrs_h' => 'Drei Jahre, drei Sätze abgenommener Arbeitsstücke',
);
